function personelInitials(p){const a=personelName(p).trim().split(/\s+/).filter(Boolean);return(a[0]?.[0]||'P')+(a.length>1?(a[a.length-1]?.[0]||''):'')}
function canEditDuty(){return !!(PermissionService?.can?.('management.duty.edit','edit')||PermissionService?.can?.('management.duty','edit')||globalThis.duzenleyebilir?.('nobet'))}
function canEditStaff(){return !!(PermissionService?.can?.('management.personnel.edit','edit')||PermissionService?.can?.('management.personnel','edit')||globalThis.duzenleyebilir?.('personel'))}
function canEditTasks(){return !!(PermissionService?.can?.('management.periodic.edit','edit')||PermissionService?.can?.('management.periodic','edit')||globalThis.duzenleyebilir?.('periyodikIsler'))}
function canEditTeacherLeaves(){return !!(PermissionService?.can?.('people.teachers.edit','edit')||PermissionService?.can?.('people.teachers','edit')||globalThis.duzenleyebilir?.('ogretmenler'))}
async function prepareLocal(){if(!SyncEngine||!COL)return;const defs={personel:COL.personel,personelIzinler:COL.personelIzinler,ogretmenIzinleri:COL.ogretmenIzinleri,hatirlaticilar:COL.hatirlaticilar,periyodikIsler:COL.periyodikIsler,periyodikSablon:COL.periyodikSablon,nobetYerleri:COL.nobetYerleri,nobetAtamalari:COL.nobetAtamalari,nobetciAmirleri:COL.nobetciAmirleri,resmiTatiller:COL.resmiTatiller,nobetRotasyon:COL.nobetRotasyon,ogretmenler:COL.ogretmenler,okulBilgileri:COL.okulBilgileri,dilekceler:COL.dilekceler};const types=[];Object.entries(defs).forEach(([t,c])=>{if(c){SyncEngine.register(t,c);types.push(t)}});if(types.length){await SyncEngine.localHydrate(types);SyncEngine.schedule(100)}}
function shell(){return`<section class="ka-stack" data-management-module><div class="ka-row ka-row--between ka-management-intro" data-management-heading><div><h2>Yönetim</h2><p class="ka-muted">Personel, görev, izin ve nöbet bilgileri cihaz verisinden açılır.</p></div><span id="managementCount" class="ka-badge"></span></div><label class="ka-field ka-management-search" data-management-search-wrap><span class="ka-field__label">Ara</span><input id="managementSearch" type="search" placeholder="Personel, görev veya tarih ara…"></label><div id="managementContent" class="ka-stack"></div></section>`}
function staff(){const list=arr('personel').filter(p=>match([p.ad,p.soyad,p.adSoyad,p.gorev,p.unvan,p.telefon,p.tc,p.kadroKademesi,(p.gorevYeriKademeleri||[]).join?.(' ')])).sort((a,b)=>personelName(a).localeCompare(personelName(b),'tr'));const edit=canEditStaff();return{count:list.length,html:`<div class="ka-row ka-row--between"><div><h3>Personeller</h3><p class="ka-muted">Hizmetli, sürekli işçi ve diğer okul personeli kayıtları</p></div>${edit?'<button class="ka-btn ka-btn--sm" type="button" data-staff-new>+ Yeni Personel</button>':''}</div>${list.length?list.map(p=>`<article class="ka-card ka-list-card"><div class="ka-card__body ka-row"><span class="ka-avatar">${esc(personelInitials(p).toLocaleUpperCase('tr'))}</span><button class="ka-grow" type="button" data-staff-detail="${esc(p.id)}" style="border:0;background:none;text-align:left;padding:0;color:inherit"><strong>${esc(personelName(p))}</strong><div class="ka-muted">${esc(p.gorev||p.unvan||'Personel')}${p.tc?' · TC '+esc(p.tc):''}${p.kadroKademesi?' · '+esc(p.kadroKademesi):''}</div></button>${p.telefon?`<a class="ka-btn ka-btn--ghost ka-btn--sm" href="tel:${esc(p.telefon)}">Ara</a>`:''}<button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-staff-detail="${esc(p.id)}">Detay</button></div></article>`).join(''):'<div class="ka-empty">Personel kaydı bulunamadı.</div>'}`}}
function staffForm(p={}){const other=p.gorev&&!PERSONEL_GOREV_SECENEKLERI.includes(p.gorev);const yer=Array.isArray(p.gorevYeriKademeleri)?p.gorevYeriKademeleri.join(', '):(p.gorevYeriKademeleri||'');return`<div class="ka-grid"><label class="ka-field"><span class="ka-field__label">Ad Soyad *</span><input data-staff-name value="${esc(personelName(p)==='Personel'?'':personelName(p))}"></label><label class="ka-field"><span class="ka-field__label">TC Kimlik No</span><input data-staff-tc maxlength="11" inputmode="numeric" value="${esc(p.tc||'')}"></label></div><div class="ka-grid"><label class="ka-field"><span class="ka-field__label">Telefon</span><input data-staff-phone value="${esc(p.telefon||'')}"></label><label class="ka-field"><span class="ka-field__label">Görev</span><select data-staff-role>${PERSONEL_GOREV_SECENEKLERI.map(x=>`<option value="${esc(x)}" ${x===p.gorev?'selected':''}>${esc(x)}</option>`).join('')}${other?`<option value="${esc(p.gorev)}" selected>${esc(p.gorev)}</option>`:''}</select></label></div><div class="ka-grid"><label class="ka-field"><span class="ka-field__label">Kadro Kademesi</span><input data-staff-cadre value="${esc(p.kadroKademesi||'')}"></label><label class="ka-field"><span class="ka-field__label">Görev Yeri / Kademeler</span><input data-staff-places value="${esc(yer)}" placeholder="Virgülle ayırabilirsiniz"></label></div><label class="ka-field"><span class="ka-field__label">Adres</span><textarea data-staff-address>${esc(p.adres||'')}</textarea></label><label class="ka-field"><span class="ka-field__label">Notlar</span><textarea data-staff-notes>${esc(p.notlar||'')}</textarea></label>`}
function staffModal(p=null){const mevcut=p||{},ov=modal(p?'Personel Düzenle':'Yeni Personel',staffForm(mevcut));if(p){const del=document.createElement('button');del.type='button';del.className='ka-btn ka-btn--danger';del.textContent='Personeli Sil';ov.querySelector('.ka-modal__footer')?.prepend(del);del.onclick=async()=>{if(!confirm(`${personelName(p)} kaydı silinsin mi?`))return;try{await PersonelService.personelSil(p.id);ov.remove();toast?.('Personel silindi.')}catch(e){if(e?.message!=='yetkisiz')toast?.('Personel silinemedi: '+(e?.message||e))}}}ov.querySelector('[data-save]').onclick=async()=>{const adSoyad=ov.querySelector('[data-staff-name]').value.trim(),tc=ov.querySelector('[data-staff-tc]').value.trim();if(!adSoyad)return toast?.('Ad Soyad zorunludur.');if(!PersonelService.tcGecerliMi(tc))return toast?.('TC Kimlik No 11 haneli rakamlardan oluşmalıdır.');const yer=ov.querySelector('[data-staff-places]').value.split(',').map(x=>x.trim()).filter(Boolean),v={adSoyad,tc,telefon:ov.querySelector('[data-staff-phone]').value.trim(),gorev:ov.querySelector('[data-staff-role]').value,kadroKademesi:ov.querySelector('[data-staff-cadre]').value.trim(),gorevYeriKademeleri:yer,adres:ov.querySelector('[data-staff-address]').value.trim(),notlar:ov.querySelector('[data-staff-notes]').value.trim()};try{await PersonelService.personelKaydet(p?.id||null,v);ov.remove();toast?.('Personel kaydedildi.')}catch(e){if(e?.message!=='yetkisiz')toast?.('Personel kaydedilemedi: '+(e?.message||e))}}}
function staffLeaveForm(p,k={}){return`<label class="ka-field"><span class="ka-field__label">Personel</span><input value="${esc(personelName(p))}" disabled></label><label class="ka-field"><span class="ka-field__label">İzin / Rapor Türü</span><select data-staff-leave-type>${PERSONEL_IZIN_TURLERI.map(x=>`<option value="${esc(x)}" ${x===k.tur?'selected':''}>${esc(x)}</option>`).join('')}${k.tur&&!PERSONEL_IZIN_TURLERI.includes(k.tur)?`<option value="${esc(k.tur)}" selected>${esc(k.tur)}</option>`:''}</select></label><div class="ka-grid"><label class="ka-field"><span class="ka-field__label">Başlangıç *</span><input type="date" data-staff-leave-start value="${esc(k.baslangic||k.baslangicTarihi||'')}"></label><label class="ka-field"><span class="ka-field__label">Bitiş *</span><input type="date" data-staff-leave-end value="${esc(k.bitis||k.bitisTarihi||'')}"></label></div><label class="ka-field"><span class="ka-field__label">Açıklama</span><textarea data-staff-leave-note>${esc(k.aciklama||k.not||'')}</textarea></label>`}
function staffLeaveModal(p,k=null){const ov=modal(k?'İzin / Rapor Düzenle':'İzin / Rapor Ekle',staffLeaveForm(p,k||{}));if(k){const del=document.createElement('button');del.type='button';del.className='ka-btn ka-btn--danger';del.textContent='Kaydı Sil';ov.querySelector('.ka-modal__footer')?.prepend(del);del.onclick=async()=>{if(!confirm('Bu izin/rapor kaydı silinsin mi?'))return;try{await PersonelService.izinSil(k.id);ov.remove();toast?.('Kayıt silindi.');staffDetailModal(p)}catch(e){if(e?.message!=='yetkisiz')toast?.('Kayıt silinemedi.')}}}ov.querySelector('[data-save]').onclick=async()=>{const baslangic=ov.querySelector('[data-staff-leave-start]').value,bitis=ov.querySelector('[data-staff-leave-end]').value;if(!PersonelService.tarihAraligiGecerliMi(baslangic,bitis))return toast?.('Başlangıç ve bitiş tarihlerini kontrol edin.');const v={personelId:p.id,personelAdi:personelName(p),tur:ov.querySelector('[data-staff-leave-type]').value,baslangic,bitis,aciklama:ov.querySelector('[data-staff-leave-note]').value.trim()};try{await PersonelService.izinKaydet(k?.id||null,v);ov.remove();toast?.('İzin/rapor kaydedildi.');staffDetailModal(p)}catch(e){if(e?.message!=='yetkisiz')toast?.('Kayıt kaydedilemedi: '+(e?.message||e))}}}
function staffDetailModal(p){document.getElementById('kaManagementStaffDetail')?.remove();const izinler=arr('personelIzinler').filter(x=>x.personelId===p.id).sort((a,b)=>String(b.baslangic||b.baslangicTarihi||'').localeCompare(String(a.baslangic||a.baslangicTarihi||''))),ov=document.createElement('div');ov.id='kaManagementStaffDetail';ov.className='ka-modal-backdrop';const yer=Array.isArray(p.gorevYeriKademeleri)?p.gorevYeriKademeleri.join(', '):(p.gorevYeriKademeleri||'');ov.innerHTML=`<section class="ka-modal" style="max-height:92dvh;overflow:auto"><div class="ka-modal__header"><div><strong>${esc(personelName(p))}</strong><div class="ka-muted">${esc(p.gorev||'Personel')}</div></div><button class="ka-icon-button" type="button" data-close>×</button></div><div class="ka-modal__body ka-stack"><article class="ka-card"><div class="ka-card__body ka-stack"><div class="ka-row ka-row--between"><span class="ka-muted">TC Kimlik No</span><strong>${esc(p.tc||'—')}</strong></div><div class="ka-row ka-row--between"><span class="ka-muted">Telefon</span><strong>${esc(p.telefon||'—')}</strong></div><div class="ka-row ka-row--between"><span class="ka-muted">Kadro / Okul</span><strong>${esc([p.kadroKademesi,yer].filter(Boolean).join(' · ')||'—')}</strong></div><div><span class="ka-muted">Adres</span><div>${esc(p.adres||'—')}</div></div>${p.notlar?`<div><span class="ka-muted">Notlar</span><div>${esc(p.notlar)}</div></div>`:''}</div></article><div class="ka-grid"><button class="ka-btn ka-btn--secondary" type="button" data-staff-dilekce>📄 Dilekçe Oluştur</button><button class="ka-btn ka-btn--secondary" type="button" data-staff-puantaj>🕘 Puantaj / İmza</button></div><section class="ka-stack"><div class="ka-row ka-row--between"><h3>İzin / Rapor Kayıtları</h3>${canEditStaff()?'<button class="ka-btn ka-btn--sm" type="button" data-staff-leave-new>+ Kayıt Ekle</button>':''}</div>${izinler.length?izinler.map(k=>`<article class="ka-card ka-list-card"><div class="ka-card__body ka-row"><div class="ka-grow"><strong>${esc(k.tur||'İzin')}</strong><div class="ka-muted">${esc(date(k.baslangic||k.baslangicTarihi))} – ${esc(date(k.bitis||k.bitisTarihi))}${k.aciklama?' · '+esc(k.aciklama):''}</div></div>${canEditStaff()?`<button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-staff-leave-edit="${esc(k.id)}">Düzenle</button>`:''}</div></article>`).join(''):'<div class="ka-empty">İzin veya rapor kaydı bulunamadı.</div>'}</section></div><div class="ka-modal__footer">${canEditStaff()?'<button class="ka-btn ka-btn--secondary" type="button" data-staff-edit>Düzenle</button>':''}<button class="ka-btn" type="button" data-close>Kapat</button></div></section>`;document.body.appendChild(ov);ov.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>ov.remove());ov.querySelector('[data-staff-edit]')?.addEventListener('click',()=>{ov.remove();staffModal(p)});ov.querySelector('[data-staff-leave-new]')?.addEventListener('click',()=>{ov.remove();staffLeaveModal(p)});ov.querySelectorAll('[data-staff-leave-edit]').forEach(b=>b.onclick=()=>{const k=arr('personelIzinler').find(x=>x.id===b.dataset.staffLeaveEdit);if(k){ov.remove();staffLeaveModal(p,k)}});ov.querySelector('[data-staff-dilekce]')?.addEventListener('click',()=>{ov.remove();document.querySelector('[data-dilekce-modal]')?.remove();document.body.insertAdjacentHTML('beforeend',dilekceForm({personelId:p.id}));_dilekceBindModal()});ov.querySelector('[data-staff-puantaj]')?.addEventListener('click',()=>{ov.remove();ptState.personelId=p.id;if(globalThis.ShellUI?.routeModule)globalThis.ShellUI.routeModule('management',{bottom:'menu',page:'puantaj',title:'Puantaj & İmza Sirküsü'});else{active='puantaj';query='';render()}})}
function bindStaff(){document.querySelector('[data-staff-new]')?.addEventListener('click',()=>staffModal());document.querySelectorAll('[data-staff-detail]').forEach(b=>b.addEventListener('click',()=>{const p=arr('personel').find(x=>x.id===b.dataset.staffDetail);if(p)staffDetailModal(p)}))}
function periodicTemplate(){const d=arr('periyodikSablon').find(x=>x.id==='sablon');return Array.isArray(d?.gorevler)?d.gorevler:[]}
function periodicGroupLabel(key){if(key==='9999-99')return'Tarihsiz';const [y,m]=key.split('-');return new Date(Number(y),Number(m)-1,1).toLocaleDateString('tr-TR',{month:'long',year:'numeric'})}
function tasks(){const all=arr('periyodikIsler').filter(p=>match([p.isAdi,p.baslangic,p.bitis,p.not])).sort((a,b)=>(a.bitis||a.baslangic||'').localeCompare(b.bitis||b.baslangic||'')),groups={};all.forEach(p=>{const k=PeriyodikService._grupAnahtari(p);(groups[k]=groups[k]||[]).push(p)});const template=periodicTemplate(),edit=canEditTasks(),today=todayISO(),cards=Object.keys(groups).sort().map(k=>`<section class="ka-stack"><div class="ka-row ka-row--between"><strong>${esc(periodicGroupLabel(k))}</strong><span class="ka-badge">${groups[k].length} görev</span></div>${groups[k].map(p=>{const late=!p.tamamlandi&&p.bitis&&p.bitis<today;return`<article class="ka-card ka-list-card"><div class="ka-card__body ka-row"><button class="ka-icon-button" type="button" data-task-toggle="${esc(p.id)}" aria-label="Durumu değiştir">${p.tamamlandi?'✓':'○'}</button><div class="ka-grow"><strong>${esc(p.isAdi||'Periyodik görev')} ${late?'<span class="ka-badge">Gecikti</span>':''}</strong><div class="ka-muted">${esc(date(p.baslangic))} – ${esc(date(p.bitis))}${p.not?' · '+esc(p.not):''}</div></div><span class="ka-badge">${p.tamamlandi?'Tamamlandı':'Bekliyor'}</span>${edit?`<button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-task-edit="${esc(p.id)}">Düzenle</button>`:''}</div></article>`}).join('')}</section>`).join('');return{count:all.length,html:`<div class="ka-row ka-row--between"><div><h3>Aylık İşler</h3><p class="ka-muted">Puantaj, ek ders, İŞKUR, taşıma ve diğer tekrarlayan idari işler</p></div>${edit?'<button class="ka-btn ka-btn--sm" type="button" data-task-new>+ Yeni İş</button>':''}</div><article class="ka-card"><div class="ka-card__body ka-stack"><div class="ka-row ka-row--between"><div><strong>Aylık Şablon</strong><div class="ka-muted">${template.length?`${template.length} görev tanımlı. Bu ayın görevlerini tek tıkla oluşturabilirsiniz.`:'Henüz şablon kaydedilmedi. Varsayılan okul rutinlerini düzenleyerek başlayabilirsiniz.'}</div></div>${edit?'<button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-task-template>Şablonu Düzenle</button>':''}</div>${edit?'<button class="ka-btn" type="button" data-task-create-month>Bu Ayın Görevlerini Oluştur</button>':''}</div></article>${all.length?cards:'<div class="ka-empty">Henüz periyodik iş eklenmedi.</div>'}`}}
function taskModal(p=null){const names=[...new Set(arr('periyodikIsler').map(x=>x.isAdi).filter(Boolean))],ov=modal(p?'Periyodik İşi Düzenle':'Yeni Periyodik İş',`<label class="ka-field"><span class="ka-field__label">İş Adı *</span><input data-task-name list="periodicTaskNames" value="${esc(p?.isAdi||'')}" placeholder="Örn: Okul Taşıma İşlemleri"><datalist id="periodicTaskNames">${names.map(x=>`<option value="${esc(x)}"></option>`).join('')}</datalist></label><div class="ka-grid"><label class="ka-field"><span class="ka-field__label">Başlangıç *</span><input type="date" data-task-start value="${esc(p?.baslangic||todayISO())}"></label><label class="ka-field"><span class="ka-field__label">Bitiş</span><input type="date" data-task-end value="${esc(p?.bitis||'')}"></label></div><label class="ka-field"><span class="ka-field__label">Not</span><textarea data-task-note>${esc(p?.not||'')}</textarea></label>${p?'<p class="ka-muted">Bitiş tarihini değiştirirseniz bildirim tekrar gönderim için sıfırlanır.</p>':''}`);if(p){const del=document.createElement('button');del.type='button';del.className='ka-btn ka-btn--danger';del.textContent='İşi Sil';ov.querySelector('.ka-modal__footer')?.prepend(del);del.onclick=async()=>{if(!confirm('Bu işi silmek istiyor musunuz?'))return;try{await PeriyodikService.isSil(p.id);ov.remove();toast?.('İş silindi.')}catch(e){if(e?.message!=='yetkisiz')toast?.('İş silinemedi.')}}}ov.querySelector('[data-save]').onclick=async()=>{const isAdi=ov.querySelector('[data-task-name]').value.trim(),baslangic=ov.querySelector('[data-task-start]').value,bitis=ov.querySelector('[data-task-end]').value;if(!isAdi||!baslangic)return toast?.('İş adı ve başlangıç tarihi zorunludur.');if(bitis&&bitis<baslangic)return toast?.('Bitiş tarihi başlangıçtan önce olamaz.');const bitisDegisti=!!p&&(p.bitis||'')!==bitis,v={isAdi,baslangic,bitis,not:ov.querySelector('[data-task-note]').value.trim(),tamamlandi:p?!!p.tamamlandi:false,bildirimGonderildi:p?(bitisDegisti?false:!!p.bildirimGonderildi):false};try{await PeriyodikService.isKaydet(p?.id||null,v);ov.remove();toast?.('Kaydedildi.')}catch(e){if(e?.message!=='yetkisiz')toast?.('Kaydedilemedi: '+(e?.message||e))}}}
function templateRow(g={}){return`<div class="ka-card" data-template-row><div class="ka-card__body ka-stack"><div class="ka-row"><label class="ka-field ka-grow"><span class="ka-field__label">İş Adı</span><input data-template-name value="${esc(g.isAdi||'')}"></label><button class="ka-icon-button" type="button" data-template-remove aria-label="Satırı kaldır">×</button></div><div class="ka-grid"><label class="ka-field"><span class="ka-field__label">Başlangıç Günü</span><input type="number" min="1" max="31" data-template-start value="${Number(g.baslangicGun)||1}"></label><label class="ka-field"><span class="ka-field__label">Bitiş Günü</span><input type="number" min="1" max="31" data-template-end value="${Number(g.bitisGun)||1}"></label></div></div></div>`}
function taskTemplateModal(){const saved=periodicTemplate(),source=saved.length?saved:PERIYODIK_SABLON_VARSAYILAN,ov=modal('Aylık Şablonu Düzenle',`<p class="ka-muted">Her ay tekrarlayan iş adını ve ayın kaçıncı günleri arasında yapılacağını tanımlayın.</p><div class="ka-stack" data-template-list>${source.map(templateRow).join('')}</div><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-template-add>+ Görev Satırı Ekle</button>`);const bindRows=()=>ov.querySelectorAll('[data-template-remove]').forEach(b=>b.onclick=()=>b.closest('[data-template-row]')?.remove());bindRows();ov.querySelector('[data-template-add]').onclick=()=>{ov.querySelector('[data-template-list]').insertAdjacentHTML('beforeend',templateRow({isAdi:'',baslangicGun:1,bitisGun:1}));bindRows()};ov.querySelector('[data-save]').onclick=async()=>{const gorevler=[...ov.querySelectorAll('[data-template-row]')].map(r=>({isAdi:r.querySelector('[data-template-name]').value.trim(),baslangicGun:Math.min(31,Math.max(1,Number(r.querySelector('[data-template-start]').value)||1)),bitisGun:Math.min(31,Math.max(1,Number(r.querySelector('[data-template-end]').value)||1))})).filter(x=>x.isAdi);try{await PeriyodikService.sabloniKaydet(gorevler);ov.remove();toast?.('Şablon kaydedildi.')}catch(e){if(e?.message!=='yetkisiz')toast?.('Şablon kaydedilemedi.')}}}
function bindTasks(){document.querySelector('[data-task-new]')?.addEventListener('click',()=>taskModal());document.querySelector('[data-task-template]')?.addEventListener('click',taskTemplateModal);document.querySelector('[data-task-create-month]')?.addEventListener('click',async()=>{const s=periodicTemplate();if(!s.length)return toast?.('Önce Şablonu Düzenle ile görevlerinizi tanımlayın.');try{const r=await PeriyodikService.buAyinGorevleriniOlustur(s,arr('periyodikIsler'));toast?.(r.olusturulan?`${r.olusturulan} görev oluşturuldu${r.atlanan?`, ${r.atlanan} zaten vardı`:''}.`:'Bu ayın tüm şablon görevleri zaten mevcut.')}catch(e){if(e?.message!=='yetkisiz')toast?.('Görevler oluşturulamadı.')}});document.querySelectorAll('[data-task-toggle]').forEach(b=>b.onclick=async()=>{const p=arr('periyodikIsler').find(x=>x.id===b.dataset.taskToggle);if(!p)return;try{await PeriyodikService.tamamlandiGuncelle(p.id,!p.tamamlandi)}catch(e){if(e?.message!=='yetkisiz')toast?.('Durum güncellenemedi.')}});document.querySelectorAll('[data-task-edit]').forEach(b=>b.onclick=()=>{const p=arr('periyodikIsler').find(x=>x.id===b.dataset.taskEdit);if(p)taskModal(p)})}
