function dutyExcelMappingModal(sheetName,rows,headerIdx,dateCol,chiefCol,columns){const ov=modal(`Excel’den İçe Aktar — ${esc(sheetName)}`,`<p class="ka-muted">“${esc(sheetName)}” sayfası algılandı. Nöbetçi Amir sütunu otomatik bulundu. Nöbet yeri adlarını kontrol edin.</p><div class="ka-stack">${columns.map(c=>`<div class="ka-grid"><label class="ka-field"><span class="ka-field__label">Sütun ${c.index+1}${c.sample?` — örn: ${esc(c.sample)}`:''}</span><input data-duty-excel-label="${c.index}" value="${esc(c.label)}"></label><label class="ka-field"><span class="ka-field__label">Kullanım</span><select data-duty-excel-role="${c.index}"><option value="place">Nöbet Yeri</option><option value="ignore">Yoksay</option></select></label></div>`).join('')}</div>`,'İçe Aktar');ov.querySelector('[data-save]').onclick=async()=>{const mappings=columns.map(c=>({index:c.index,etiket:ov.querySelector(`[data-duty-excel-label="${c.index}"]`).value.trim(),rol:ov.querySelector(`[data-duty-excel-role="${c.index}"]`).value})).filter(x=>x.rol==='place'&&x.etiket);if(!mappings.length)return toast?.('En az bir nöbet yeri eşlemesi gerekli.');ov.querySelector('[data-save]').disabled=true;try{const r=await NobetService.exceliUygula({satirlar:rows,baslikIdx:headerIdx,tarihCol:dateCol,amirCol:chiefCol,eslemeler:mappings,nobetYerleri:arr('nobetYerleri'),nobetAtamalari:arr('nobetAtamalari'),nobetciAmirleri:arr('nobetciAmirleri'),ogretmenler:arr('ogretmenler')});ov.remove();toast?.(`İçe aktarıldı: ${r.gunSayisi} gün · ${r.atamaSayisi} nöbet ataması · ${r.amirSayisi} amir ataması.`)}catch(e){ov.querySelector('[data-save]').disabled=false;toast?.(e?.message==='yetkisiz'?'Bu işlem için yetkiniz yok.':e?.message||'Excel içe aktarılamadı.')}}}
async function readDutyExcel(file){if(!file)return;try{const XLSX=await ensureDutyXlsx(),wb=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true}),sheets=wb.SheetNames.filter(n=>!/^veri$|^data$|^referans$/i.test(String(n).trim()));if(!sheets.length)throw new Error('Uygun ay sayfası bulunamadı.');const sheetName=sheets[sheets.length-1],rows=XLSX.utils.sheet_to_json(wb.Sheets[sheetName],{header:1,defval:''});let headerIdx=-1,chiefCol=-1;for(let i=0;i<Math.min(6,rows.length);i++){const c=(rows[i]||[]).findIndex(h=>/amir/i.test(String(h)));if(c>-1){headerIdx=i;chiefCol=c;break}}if(headerIdx<0)throw new Error(`“${sheetName}” sayfasında NÖBETÇİ AMİR başlığı bulunamadı.`);const found=(rows[headerIdx]||[]).findIndex(h=>/tarih|gün|date/i.test(String(h))),dateCol=found>-1?found:0,sub=rows[headerIdx+1]||[],sampleRow=rows.slice(headerIdx+2).find(r=>(r||[]).some(v=>v!==''))||[],columns=[];for(let c=dateCol+1;c<chiefCol;c++)columns.push({index:c,label:String(sub[c]||'').trim()||`Sütun ${c+1}`,sample:NobetService.excelAdiSadelestir(sampleRow[c]||'')});dutyExcelMappingModal(sheetName,rows,headerIdx,dateCol,chiefCol,columns)}catch(e){toast?.('Excel okunamadı: '+(e?.message||e))}}
function dutyExcelModal(){const ov=modal('📥 Nöbet Excel’den İçe Aktar','<p class="ka-muted">Excel dosyasındaki en güncel ay sekmesi kullanılır. “Nöbetçi Amir” ve tarih sütunları otomatik algılanır.</p><label class="ka-field"><span class="ka-field__label">Excel Dosyası</span><input type="file" data-duty-excel-file accept=".xlsx,.xls,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-excel"></label>');ov.querySelector('[data-save]').hidden=true;ov.querySelector('[data-duty-excel-file]').onchange=e=>{const file=e.target.files?.[0];if(file){ov.remove();readDutyExcel(file)}}}
