function assignmentModal(iso,placeId){const place=arr('nobetYerleri').find(x=>x.id===placeId),current=arr('nobetAtamalari').find(x=>x.tarih===iso&&x.yerId===placeId),teachers=[...arr('ogretmenler')].sort((a,b)=>teacherName(a).localeCompare(teacherName(b),'tr')),ov=modal(current?'Nöbet Atamasını Düzenle':'Nöbet Ata',`<div class="ka-field"><span class="ka-field__label">Tarih / Yer</span><input value="${esc(date(iso))} — ${esc(place?.ad||'')}" disabled></div><label class="ka-field"><span class="ka-field__label">Nöbetçi Öğretmen</span><select data-teacher><option value="">Seçiniz</option>${teachers.map(o=>`<option value="${esc(o.id)}" ${current?.ogretmenId===o.id?'selected':''}>${esc(teacherName(o))}</option>`).join('')}</select></label>${current?'<button class="ka-btn ka-btn--danger ka-btn--sm" type="button" data-delete>Atamayı Kaldır</button>':''}`);ov.querySelector('[data-save]').onclick=async()=>{const id=ov.querySelector('[data-teacher]').value,o=teachers.find(x=>x.id===id);if(!o)return toast?.('Öğretmen seçimi zorunludur.');await NobetService.atamaKaydet(current?.id||null,{tarih:iso,yerId:placeId,ogretmenAdSoyad:teacherName(o),ogretmenId:o.id});ov.remove();toast?.('Nöbet ataması kaydedildi.')};ov.querySelector('[data-delete]')?.addEventListener('click',async()=>{if(!confirm('Bu atamayı kaldırmak istiyor musunuz?'))return;await NobetService.atamaSil(current.id);ov.remove()})}
