function autoModal(){const places=NobetService.yerSirali(arr('nobetYerleri')),teachers=[...arr('ogretmenler')].sort((a,b)=>teacherName(a).localeCompare(teacherName(b),'tr'));if(places.length<2)return toast?.('Otomatik dağıtım için en az 2 nöbet yeri gerekli.');if(!teachers.length)return toast?.('Öğretmen listesi boş.');const rotation=arr('nobetRotasyon').find(x=>x.id==='sablon')||{},days=['Pazartesi','Salı','Çarşamba','Perşembe','Cuma'],opts=teachers.map(o=>`<option value="${esc(o.id)}">${esc(teacherName(o))}</option>`).join(''),placeOpts=places.map(p=>`<option value="${esc(p.id)}">${esc(p.ad)}</option>`).join(''),refs=rotation.referansHafta||{},ov=modal('Otomatik Nöbet Dağıtımı',`<div class="ka-grid"><label class="ka-field"><span class="ka-field__label">1. Nöbet Yeri</span><select data-place-a>${placeOpts}</select></label><label class="ka-field"><span class="ka-field__label">2. Nöbet Yeri</span><select data-place-b>${placeOpts}</select></label></div><div class="ka-duty-auto-grid">${days.map((day,i)=>`<div><strong>${day}</strong><select data-ref-a="${i+1}"><option value="">Öğretmen seçin</option>${opts}</select><select data-ref-b="${i+1}"><option value="">Öğretmen seçin</option>${opts}</select></div>`).join('')}</div><label class="ka-field"><span class="ka-field__label">Nöbetçi Amirler (Ctrl/⌘ ile çoklu seçim)</span><select data-chiefs multiple size="${Math.min(6,Math.max(3,teachers.length))}">${teachers.map(o=>`<option value="${esc(o.id)}" ${Array.isArray(rotation.amirListesi)&&rotation.amirListesi.includes(o.id)?'selected':''}>${esc(teacherName(o))}</option>`).join('')}</select></label>`,'Programı Oluştur');const pa=ov.querySelector('[data-place-a]'),pb=ov.querySelector('[data-place-b]');pa.value=rotation.yerler?.bahce||places[0]?.id||'';pb.value=rotation.yerler?.bina||places[1]?.id||places[0]?.id||'';for(let i=1;i<=5;i++){ov.querySelector(`[data-ref-a="${i}"]`).value=refs[i]?.bahce||'';ov.querySelector(`[data-ref-b="${i}"]`).value=refs[i]?.bina||''}ov.querySelector('[data-save]').onclick=async()=>{if(!pa.value||!pb.value||pa.value===pb.value)return toast?.('İki farklı nöbet yeri seçin.');const referansHafta={};for(let i=1;i<=5;i++){referansHafta[i]={bahce:ov.querySelector(`[data-ref-a="${i}"]`).value,bina:ov.querySelector(`[data-ref-b="${i}"]`).value};if(!referansHafta[i].bahce||!referansHafta[i].bina)return toast?.('Her gün için iki öğretmen seçin.')}const amirListesi=[...ov.querySelector('[data-chiefs]').selectedOptions].map(x=>x.value);if(!confirm(`${new Date(dutyYear,dutyMonth,1).toLocaleDateString('tr-TR',{month:'long',year:'numeric'})} nöbet programı yeniden oluşturulsun mu?`))return;const sonuc=await NobetService.otomatikDagitimUygula({hedefYil:dutyYear,hedefAy:dutyMonth,bahceYerId:pa.value,binaYerId:pb.value,referansHafta,amirListesi,mevcutAmirSayac:rotation.amirSayac||0,nobetAtamalari:arr('nobetAtamalari'),nobetciAmirleri:arr('nobetciAmirleri'),ogretmenler:teachers,nobetTatilMiFn:iso=>!!arr('resmiTatiller').find(t=>t.tarih===iso)});ov.remove();toast?.(`Program oluşturuldu: ${sonuc.toplamAtama} atama · ${sonuc.toplamAmir} amir.`)}}
