const DUTY_REPORT_COLUMNS=[
  {label:'BAHÇE',aliases:['Bahçe']},
  {label:'OKUL BİNASI',aliases:['Okul Binası']},
  {label:'GİRİŞ - BAHÇE',aliases:['Giriş - Bahçe','Giriş-Bahçe']}
];
function dutyReportPlace(places,aliases){const wanted=new Set(aliases.map(norm));return places.find(p=>wanted.has(norm(p.ad||'')))||null}
function dutyReportFirstWorkday(y,m,tatiller=arr('resmiTatiller')){const total=new Date(y,m+1,0).getDate();for(let d=1;d<=total;d++){const day=new Date(y,m,d).getDay(),iso=NobetService.tarihISO(y,m,d);if(day!==0&&day!==6&&!(tatiller||[]).some(t=>t.tarih===iso))return iso}return NobetService.tarihISO(y,m,1)}
function dutyReportLongDate(y,m,d){return new Date(y,m,d).toLocaleDateString('tr-TR',{day:'numeric',month:'long',year:'numeric',weekday:'long'})}
function dutyReportDisplayDate(iso){if(!iso)return'';const d=new Date(iso+'T00:00:00');return Number.isNaN(d.getTime())?iso:d.toLocaleDateString('tr-TR',{day:'numeric',month:'long',year:'numeric'})}
function dutyReportDocumentDate(){return new Date().toLocaleDateString('tr-TR',{day:'numeric',month:'long',year:'numeric'})}
function dutyReportLogoUrl(){try{return new URL('assets/logo.png',globalThis.location.href).href}catch(_){return'assets/logo.png'}}
function dutyReportPrincipal(okul){const teacher=arr('ogretmenler').find(o=>o.id===okul?.mudurId);return teacher?{ad:teacherName(teacher),telefon:teacher.telefon||''}:{ad:String(okul?.mudurAdi||okul?.mudur||'').trim()||'—',telefon:String(okul?.mudurTelefon||'').trim()}}
function dutyReportModal(){const selected=`${dutyYear}-${String(dutyMonth+1).padStart(2,'0')}`,first=dutyReportFirstWorkday(dutyYear,dutyMonth),ov=modal('Nöbet Raporu',`<label class="ka-field"><span class="ka-field__label">Ay</span><input type="month" data-month value="${selected}"></label><label class="ka-field"><span class="ka-field__label">Geçerlilik Tarihi</span><input type="date" data-validity value="${first}"></label><label class="ka-field"><span class="ka-field__label">Sayfa yönü</span><select data-orientation><option value="dikey">Dikey A4</option><option value="yatay">Yatay A4</option></select></label>`,'Önizle');const monthInput=ov.querySelector('[data-month]'),validity=ov.querySelector('[data-validity]');monthInput.addEventListener('change',()=>{const [ys,ms]=String(monthInput.value||'').split('-'),y=Number(ys),m=Number(ms)-1;if(y&&m>=0)validity.value=dutyReportFirstWorkday(y,m)});ov.querySelector('[data-save]').onclick=async()=>{await createDutyReport(monthInput.value,ov.querySelector('[data-orientation]').value,validity.value);ov.remove()}}
async function createDutyReport(month,yon,gecerlilikTarihi=''){if(!globalThis.ReportEngine)await AppLoader.loadScript('js/modules/report-engine.js');const [ys,ms]=String(month).split('-'),y=Number(ys),m=Number(ms)-1;if(!y||m<0)return;const places=NobetService.yerSirali(arr('nobetYerleri')),atamalar=arr('nobetAtamalari'),amirler=arr('nobetciAmirleri'),tatiller=arr('resmiTatiller'),okulRows=arr('okulBilgileri'),okul=okulRows.find(x=>x.id==='ayarlar')||okulRows[0]||{},okulAdi=okul.okulAdi||okul.ad||'KORUK İLK - ORTAOKULU',okulBaslik=String(okulAdi).replace(/\s*[-–]\s*/g,' - ').replace(/\s+/g,' ').trim(),mudur=dutyReportPrincipal(okul),columns=DUTY_REPORT_COLUMNS.map(c=>({...c,place:dutyReportPlace(places,c.aliases)})),gunSayisi=new Date(y,m+1,0).getDate(),rows=[];for(let g=1;g<=gunSayisi;g++){const iso=NobetService.tarihISO(y,m,g),dt=new Date(y,m,g),haftasonu=dt.getDay()===0||dt.getDay()===6,tatil=tatiller.find(t=>t.tarih===iso),tarihMetin=dutyReportLongDate(y,m,g);if(tatil){const aciklama=String(tatil.aciklama||tatil.ad||tatil.adi||'RESMİ TATİL').trim(),gunAy=dt.toLocaleDateString('tr-TR',{day:'numeric',month:'long'}).toLocaleUpperCase('tr'),etiket=aciklama.toLocaleUpperCase('tr').includes(gunAy)?aciklama.toLocaleUpperCase('tr'):`${gunAy} ${aciklama.toLocaleUpperCase('tr')}`;rows.push(`<tr class="ka-duty-report-holiday"><td>${esc(tarihMetin)}</td><td colspan="4">${esc(etiket)}</td></tr>`);continue}if(haftasonu){rows.push(`<tr class="ka-duty-report-weekend"><td>${esc(tarihMetin)}</td><td colspan="4"></td></tr>`);continue}const cells=columns.map(c=>{const a=c.place?atamalar.find(x=>x.tarih===iso&&x.yerId===c.place.id):null;return`<td>${esc(String(a?.ogretmenAdSoyad||'').toLocaleUpperCase('tr'))}</td>`}).join(''),amir=amirler.find(a=>a.tarih===iso);rows.push(`<tr><td>${esc(tarihMetin)}</td>${cells}<td>${esc(String(amir?.ad||'').toLocaleUpperCase('tr'))}</td></tr>`)}const monthName=new Date(y,m,1).toLocaleDateString('tr-TR',{month:'long'}).toLocaleUpperCase('tr'),validity=gecerlilikTarihi||dutyReportFirstWorkday(y,m,tatiller),validityText=dutyReportDisplayDate(validity),documentDate=dutyReportDocumentDate(),chiefPhones=[];amirler.filter(a=>String(a.tarih||'').startsWith(`${ys}-${ms}`)&&a.ad).forEach(a=>{const teacher=a.ogretmenId?arr('ogretmenler').find(o=>o.id===a.ogretmenId):null,name=String(a.ad||'').trim(),phone=String(a.telefon||teacher?.telefon||'').trim();if(name&&!chiefPhones.some(x=>x.ad.localeCompare(name,'tr',{sensitivity:'base'})===0))chiefPhones.push({ad:name,telefon:phone})});const phones=[];if(mudur.ad&&mudur.ad!=='—')phones.push(mudur);chiefPhones.forEach(x=>{if(!phones.some(p=>p.ad.localeCompare(x.ad,'tr',{sensitivity:'base'})===0))phones.push(x)});const phonesHtml=phones.length?`<section class="ka-duty-report-phones"><strong>TELEFONLAR</strong>${phones.map(p=>`<span><b>${esc(String(p.ad).toLocaleUpperCase('tr'))}</b> ${esc(p.telefon||'—')}</span>`).join('')}</section>`:'',orientation=yon==='yatay'?'landscape':'portrait',body=`<section class="ka-duty-report ka-duty-report--${orientation}"><header class="ka-duty-report-banner"><img class="ka-duty-report-logo" src="${esc(dutyReportLogoUrl())}" alt=""><h1>${esc(okulBaslik.toLocaleUpperCase('tr'))} ${y} YILI ${esc(monthName)} AYI ÖĞRETMEN NÖBET ÇİZELGESİ</h1></header><table class="ka-duty-report-table"><colgroup><col class="ka-duty-report-col-date"><col class="ka-duty-report-col-garden"><col class="ka-duty-report-col-building"><col class="ka-duty-report-col-entry"><col class="ka-duty-report-col-chief"></colgroup><thead><tr><th>TARİH / GÜN</th>${columns.map(c=>`<th>${esc(c.label)}</th>`).join('')}<th>NÖBETÇİ AMİR</th></tr></thead><tbody>${rows.join('')}</tbody></table>${phonesHtml}<section class="ka-duty-report-tasks"><h2>NÖBETÇİ ÖĞRETMENİN GÖREVLERİ</h2><ol>${DUTY_TASKS.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></section><footer class="ka-duty-report-footer"><div class="ka-duty-report-footer-copy"><p>Bu çizelge ${esc(validityText)} tarihinden itibaren geçerlidir.</p><p>Öğretmen arkadaşların okuldaki eğitim öğretim hizmetlerinin verimli geçmesi için yukarıda sayılan talimatlara göre nöbet hizmetlerini yerine getirmelerini rica ederim.</p></div><div class="ka-duty-report-signature"><span>${esc(documentDate)}</span><strong>${esc(String(mudur.ad||'—').toLocaleUpperCase('tr'))}</strong><span>Okul Müdürü</span></div></footer></section>`;return ReportEngine.printReport('Öğretmen Nöbet Çizelgesi',body,{fileName:`Nobet_Cizelgesi_${ys}_${ms}`,yon:yon==='yatay'?'yatay':'dikey',okulAdi,logoGoster:false,tarihGoster:false,baslikGoster:false,compact:true,fontSize:7,kenarBosluk:5})}
function bindDuty(){document.querySelector('[data-duty-places]')?.addEventListener('click',dutyPlacesModal);document.querySelector('[data-duty-excel]')?.addEventListener('click',dutyExcelModal);document.querySelector('[data-duty-holiday-add]')?.addEventListener('click',holidayModal);document.querySelector('[data-duty-auto]')?.addEventListener('click',autoModal);document.querySelectorAll('[data-duty-report]').forEach(b=>b.addEventListener('click',dutyReportModal));document.querySelectorAll('[data-duty-month]').forEach(b=>b.onclick=()=>{dutyMonth+=Number(b.dataset.dutyMonth);if(dutyMonth<0){dutyMonth=11;dutyYear--}if(dutyMonth>11){dutyMonth=0;dutyYear++}render()});document.querySelectorAll('[data-duty-cell]').forEach(b=>b.onclick=()=>assignmentModal(b.dataset.dutyCell,b.dataset.dutyPlace));document.querySelectorAll('[data-duty-chief]').forEach(b=>b.onclick=()=>chiefModal(b.dataset.dutyChief));document.querySelectorAll('[data-duty-holiday-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Bu tatili listeden kaldırmak istiyor musunuz?'))return;await NobetService.tatilSil(b.dataset.dutyHolidayDelete)});document.querySelectorAll('[data-duty-book]').forEach(c=>c.onchange=async()=>{const a=arr('nobetAtamalari').find(x=>x.id===c.dataset.dutyBook);if(!a)return;try{await NobetService.defterDolduToggle(a,c.checked);toast?.(c.checked?'✅ Nöbet defteri işaretlendi.':'İşaret kaldırıldı.')}catch(e){c.checked=!c.checked;toast?.('Bu nöbet size ait değil.')}})}
function render(){if(!mounted)return;const module=document.querySelector('[data-management-module]'),heading=document.querySelector('[data-management-heading]');module?.classList.toggle('is-duty-page',active==='duty');module?.classList.toggle('is-payroll-page',active==='puantaj');if(heading)heading.hidden=active==='puantaj';const searchWrap=document.querySelector('[data-management-search-wrap]');if(searchWrap)searchWrap.hidden=['puantaj','dilekce'].includes(active);const out=document.getElementById('managementContent'),c=document.getElementById('managementCount');if(active==='puantaj'){if(out)out.innerHTML=puantaj();if(c)c.textContent='';bindPuantaj();PermissionService?.apply?.(out);return}if(active==='dilekce'){if(out)out.innerHTML=dilekce();if(c)c.textContent=`${arr('dilekceler').length} kayıt`;bindDilekce();PermissionService?.apply?.(out);return}const r=active==='tasks'?tasks():active==='leaves'?leaves():active==='duty'?duty():staff();if(out)out.innerHTML=r.html;if(c)c.textContent=`${r.count} kayıt`;if(active==='staff')bindStaff();if(active==='tasks')bindTasks();if(active==='leaves')bindLeaves();if(active==='duty')bindDuty();PermissionService?.apply?.(document.getElementById('v2ModuleRoot')||document)}
